function resonanceIndex(B) {
  let best = -1, dist = 999;
  peaks.forEach((p, i) => {
    const dB = Math.abs(B - p.b);
    if (dB <= 0.12 && dB < dist) { best = i; dist = dB; }
  });
  return best;
}

function updateField(value) {
  const B = Number(value);
  document.getElementById('fieldValue').textContent = B.toFixed(1);
  activePeakIndex = resonanceIndex(B);
  activeStrength = activePeakIndex >= 0 ? peaks[activePeakIndex].h : 0;
  peakHighlights.forEach((h, i) => {
    h.material.opacity = i === activePeakIndex ? 0.72 : 0.0;
  });
}

