function tweenSliderTo(target, duration = 650) {
  const slider = document.getElementById('magneticFieldStrength');
  const start = Number(slider.value);
  const t0 = performance.now();
  function tick(now) {
    const u = Math.min(1, (now - t0) / duration);
    const eased = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    slider.value = (start + (target - start) * eased).toFixed(1);
    updateField(slider.value);
    if (u < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

window.goToStep = function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  document.getElementById('stepNarration').innerHTML = '<b>' + step.title + '</b><br>' + step.narration;
  tweenSliderTo(step.state.magneticFieldStrength);
};

