function interactionLoop(now) {
  requestAnimationFrame(interactionLoop);

  const pulse = 0.55 + 0.45 * Math.sin(now * 0.012);
  const glowOpacity = activePeakIndex >= 0 ? Math.min(0.75, 0.18 + activeStrength * 0.34) * pulse : 0;
  glowShell.material.opacity = glowOpacity * 0.34;
  glowGroup.children.forEach((child, i) => {
    if (child.material && child !== glowShell) {
      child.material.opacity = glowOpacity * (0.55 + (i % 3) * 0.15);
      const sc = activePeakIndex >= 0 ? 1 + pulse * 0.85 : 1;
      child.scale.setScalar(sc);
    }
  });
  peakHighlights.forEach((h, i) => {
    if (i === activePeakIndex) h.material.opacity = 0.35 + 0.45 * pulse;
  });

  resetCableColor(greenCable1); resetCableColor(greenCable2);
  resetCableColor(blueCable1); resetCableColor(blueCable2);
  resetCableColor(blueCable3); resetCableColor(blueCable4);

  const dt = now - pathStart;
  if (dt >= 0 && dt < 4300) {
    const stage = Math.floor(dt / 850);
    if (stage === 0) {
      setCableColor(greenCable1, 0xffff33); setCableColor(greenCable2, 0xffff33); flashOutline('generator');
    } else if (stage === 1) {
      flashOutline('coil');
      glowShell.material.opacity = Math.max(glowShell.material.opacity, 0.45);
    } else if (stage === 2) {
