function cylinderBetween(a, b, radius, material, radialSegments = 10) {
  const start = a.clone ? a : new THREE.Vector3(a[0], a[1], a[2]);
  const end = b.clone ? b : new THREE.Vector3(b[0], b[1], b[2]);
  const mid = start.clone().add(end).multiplyScalar(0.5);
  const len = start.distanceTo(end);
  const geom = new THREE.CylinderGeometry(radius, radius, len, radialSegments);
  const mesh = new THREE.Mesh(geom, material);
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), end.clone().sub(start).normalize());
  return mesh;
}

function makeCable(points, material, radius = 0.025) {
  const group = new THREE.Group();
  group.userData.baseColor = material.color.clone();
  group.userData.parts = [];
  for (let i = 0; i < points.length - 1; i++) {
    const seg = cylinderBetween(points[i], points[i + 1], radius, material, 10);
    group.add(seg);
    group.userData.parts.push(seg);
  }
  for (const p of points) {
    const s = new THREE.Mesh(new THREE.SphereGeometry(radius * 1.2, 10, 8), material);
    s.position.copy(p);
    group.add(s);
    group.userData.parts.push(s);
  }
  scene.add(group);
  return group;
}

function setCableColor(group, hex) {
  group.traverse(o => {
    if (o.material && o.material.color) o.material.color.setHex(hex);
  });
}

function resetCableColor(group) {
  group.traverse(o => {
    if (o.material && o.material.color && group.userData.baseColor) o.material.color.copy(group.userData.baseColor);
  });
}

