function interactionLoop(now) {
  requestAnimationFrame(interactionLoop);

  const pulse = 0.55 + 0.45 * Math.sin(now * 0.012);
  const glowOpacity = activePeakIndex >= 0 ? Math.min(0.32, 0.08 + activeStrength * 0.14) * pulse : 0;
  glowShell.material.opacity = glowOpacity * 0.32;
  glowGroup.children.forEach((child, i) => {
    if (child.material && child !== glowShell) {
      child.material.opacity = glowOpacity * (0.48 + (i % 3) * 0.10);
      const sc = activePeakIndex >= 0 ? 1 + pulse * 0.30 : 1;
      child.scale.setScalar(sc);
    }
  });

  peakHighlights.forEach((h, i) => {
    if (i === activePeakIndex) h.material.opacity = 0.14 + 0.16 * pulse;
  });

  resetCableColor(greenCable1); resetCableColor(greenCable2);
  resetCableColor(blueCable1); resetCableColor(blueCable2);
  resetCableColor(blueCable3); resetCableColor(blueCable4);

  const dt = now - pathStart;
  if (dt >= 0 && dt < 4300) {
    const stage = Math.floor(dt / 850);
    if (stage === 0) {
      setCableColor(greenCable1, 0xffee44); setCableColor(greenCable2, 0xffee44); flashOutline('generator');
    } else if (stage === 1) {
      flashOutline('coil');
      glowShell.material.opacity = Math.max(glowShell.material.opacity, 0.20);
    } else if (stage === 2) {
      setCableColor(blueCable1, 0xffee44); setCableColor(blueCable2, 0xffee44); flashOutline('detector');
    } else if (stage === 3) {
      setCableColor(blueCable3, 0xffee44); setCableColor(blueCable4, 0xffee44);
    } else if (stage === 4) {
      flashOutline('monitor');
      peakHighlights.forEach(h => h.material.opacity = Math.max(h.material.opacity, 0.22 * pulse));
    }
  }
}
requestAnimationFrame(interactionLoop);
